#include "PythonHost.h"

// Python.h must come first (it sets up Windows/CRT macros for the interpreter build).
#include <Python.h>

#include <windows.h>

#include <string>

#include <winrt/Windows.Foundation.Collections.h>
#include <winrt/Windows.System.UserProfile.h>

#include "Log.h"

// Generated by renpy/uwp/gen_static.py: registers Ren'Py's C/Cython modules as built-ins.
extern "C" int renpy_uwp_extend_inittab(void);
// BenchModule.cpp: host diagnostics module.
extern "C" PyObject* PyInit__renpy_uwp(void);

namespace renpyuwp::python {

namespace {

std::wstring g_localState;
std::wstring g_installDir;

// First preferred language of the user (e.g. "es-MX", "en-US"), for the IsroTaxo menu.
std::wstring UserLanguage() {
    try {
        auto langs = winrt::Windows::System::UserProfile::GlobalizationPreferences::Languages();
        if (langs.Size() > 0) return std::wstring(langs.GetAt(0).c_str());
    } catch (...) {
    }
    return L"";
}

bool CheckStatus(PyStatus status, const char* what) {
    if (!PyStatus_Exception(status)) return true;
    RLOG("python: %s FAILED: %s%s%s (exitcode %d)", what, status.func ? status.func : "",
         status.func ? ": " : "", status.err_msg ? status.err_msg : "?", status.exitcode);
    return false;
}

// Logs the pending Python exception with its traceback (sys.stderr may be None in UWP).
void LogPythonError(const char* where) {
    PyObject *type = nullptr, *value = nullptr, *tb = nullptr;
    PyErr_Fetch(&type, &value, &tb);
    PyErr_NormalizeException(&type, &value, &tb);
    RLOG("python: exception in %s", where);
    PyObject* tbmod = PyImport_ImportModule("traceback");
    PyObject* lines = nullptr;
    if (tbmod && type) {
        lines = PyObject_CallMethod(tbmod, "format_exception", "OOO", type, value ? value : Py_None,
                                    tb ? tb : Py_None);
    }
    if (lines && PyList_Check(lines)) {
        for (Py_ssize_t i = 0; i < PyList_GET_SIZE(lines); ++i) {
            const char* s = PyUnicode_AsUTF8(PyList_GET_ITEM(lines, i));
            if (s) RLOG("python:   %s", s);
        }
    } else {
        PyErr_Clear();
        PyObject* str = value ? PyObject_Str(value) : nullptr;
        const char* s = str ? PyUnicode_AsUTF8(str) : nullptr;
        RLOG("python:   %s", s ? s : "<no message>");
        Py_XDECREF(str);
    }
    Py_XDECREF(lines);
    Py_XDECREF(tbmod);
    Py_XDECREF(type);
    Py_XDECREF(value);
    Py_XDECREF(tb);
    PyErr_Clear();
}

bool SetSysString(const char* name, const std::wstring& value) {
    PyObject* v = PyUnicode_FromWideChar(value.c_str(), static_cast<Py_ssize_t>(value.size()));
    if (!v) return false;
    int rc = PySys_SetObject(name, v);
    Py_DECREF(v);
    return rc == 0;
}

int RunInterpreter(const char* const* entries, int count) {
    if (renpy_uwp_extend_inittab() != 0 || PyImport_AppendInittab("_renpy_uwp", PyInit__renpy_uwp) != 0) {
        RLOG("python: registering built-in modules failed");
        return count;
    }
    PyPreConfig pre;
    PyPreConfig_InitIsolatedConfig(&pre);
    pre.utf8_mode = 1;
    if (!CheckStatus(Py_PreInitialize(&pre), "Py_PreInitialize")) return 1;

    PyConfig config;
    PyConfig_InitIsolatedConfig(&config);
    // Paths relative to the package folder (the process working directory), as Kodi does:
    // absolute paths into the install folder are restricted inside an app container.
    bool ok = CheckStatus(PyConfig_SetString(&config, &config.home, L"python"), "set home") &&
              CheckStatus(PyConfig_SetString(&config, &config.program_name, L"RenpyUWP"), "set program_name");
    config.module_search_paths_set = 1;
    ok = ok &&
         CheckStatus(PyWideStringList_Append(&config.module_search_paths, L"python\\python312.zip"), "path zip") &&
         CheckStatus(PyWideStringList_Append(&config.module_search_paths, L"python"), "path dir") &&
         CheckStatus(PyWideStringList_Append(&config.module_search_paths, L"python\\renpy.zip"), "path renpy");
    config.write_bytecode = 0;
    config.install_signal_handlers = 0;
    config.parse_argv = 0;
    config.site_import = 0;
    config.safe_path = 1;
    config.user_site_directory = 0;
    config.buffered_stdio = 0;
    if (!ok) {
        PyConfig_Clear(&config);
        return 1;
    }
    RLOG("python: Py_InitializeFromConfig (home=python, paths=python\\python312.zip;python;python\\renpy.zip)");
    PyStatus st = Py_InitializeFromConfig(&config);
    PyConfig_Clear(&config);
    if (!CheckStatus(st, "Py_InitializeFromConfig")) return 1;
    RLOG("python: initialized: %s", Py_GetVersion());

    int failures = 0;
    std::wstring lang = UserLanguage();
    RLOG("python: user language %ls", lang.empty() ? L"(unknown)" : lang.c_str());
    if (!SetSysString("_renpy_uwp_localstate", g_localState) || !SetSysString("_renpy_uwp_install", g_installDir) ||
        !SetSysString("_renpy_uwp_language", lang)) {
        LogPythonError("setting sys attributes");
        failures = count;
    } else {
        for (int i = 0; i < count; ++i) {
            std::string entry = entries[i];
            std::string mod = entry.substr(0, entry.find('.'));
            std::string fn = entry.substr(entry.find('.') + 1);
            RLOG("python: running %s", entry.c_str());
            PyObject* m = PyImport_ImportModule(mod.c_str());
            if (!m) {
                LogPythonError(entry.c_str());
                ++failures;
                continue;
            }
            PyObject* result = PyObject_CallMethod(m, fn.c_str(), nullptr);
            if (!result) {
                LogPythonError(entry.c_str());
                ++failures;
            } else {
                long rc = PyLong_Check(result) ? PyLong_AsLong(result) : 0;
                RLOG("python: %s returned %ld", entry.c_str(), rc);
                if (rc != 0) ++failures;
                Py_DECREF(result);
            }
            Py_DECREF(m);
        }
    }

    int fin = Py_FinalizeEx();
    RLOG("python: Py_FinalizeEx returned %d", fin);
    return failures;
}

}  // namespace

int RunBlocking(const std::wstring& localState, const std::wstring& installDir, const char* const* entries,
                int count) {
    g_localState = localState;
    g_installDir = installDir;
    ULONG_PTR low = 0, high = 0;
    GetCurrentThreadStackLimits(&low, &high);
    RLOG("python: running on the SDL thread, stack %llu KB", static_cast<unsigned long long>((high - low) / 1024));
    int failures = RunInterpreter(entries, count);
    RLOG("python: finished, %d failing entr%s", failures, failures == 1 ? "y" : "ies");
    return failures;
}

}  // namespace renpyuwp::python
